1	// Test helpers: spawn server.mjs as a child process, talk HTTP to it, clean up after.
2	import { spawn } from 'node:child_process';
3	import { mkdtemp, rm } from 'node:fs/promises';
4	import http from 'node:http';
5	import net from 'node:net';
6	import os from 'node:os';
7	import path from 'node:path';
8	import { fileURLToPath } from 'node:url';
9	import assert from 'node:assert/strict';
10	
11	export const SERVER_PATH = fileURLToPath(new URL('../../server.mjs', import.meta.url));
12	export const JSON_TYPE = 'application/json; charset=utf-8';
13	const START_TIMEOUT_MS = 5000;
14	const STRIPPED_ENV = ['PORT', 'DATA_FILE', 'NODE_TEST_CONTEXT', 'NODE_OPTIONS'];
15	
16	function baseEnv(extra) {
17	  const env = { ...process.env };
18	  for (const key of STRIPPED_ENV) delete env[key];
19	  for (const [key, value] of Object.entries(extra)) {
20	    if (value === undefined) delete env[key];
21	    else env[key] = value;
22	  }
23	  return env;
24	}
