26	/** Creates a fresh temp folder; returns its path. Remove it with removeDir. */
27	export function makeTempDir() {
28	  return mkdtemp(path.join(os.tmpdir(), 'booking-test-'));
29	}
30	
31	export function removeDir(dir) {
32	  return rm(dir, { recursive: true, force: true });
33	}
34	
35	/** Runs fn(dir) in a fresh temp folder and removes the folder afterwards. */
36	export async function withTemp(fn) {
37	  const dir = await makeTempDir();
38	  try {
39	    return await fn(dir);
40	  } finally {
41	    await removeDir(dir);
42	  }
43	}
