45	let dateCounter = 0;
46	/**
47	 * A valid date (days 1-28) not handed out before in this process, so tests never overlap.
48	 * Starts in `baseYear`; the counter is shared by every caller in the process.
49	 */
50	export function uniqueDate(baseYear = 2060) {
51	  const n = dateCounter++;
52	  const year = baseYear + Math.floor(n / 336);
53	  const month = Math.floor((n % 336) / 28) + 1;
54	  const day = (n % 28) + 1;
55	  return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
56	}
