58	/** Asserts an error reply: exact status, exact `{ error }` body and the JSON content type. */
59	export function expectError(res, status, message) {
60	  assert.equal(res.status, status);
61	  assert.deepEqual(res.json(), { error: message });
62	  assert.equal(res.headers['content-type'], JSON_TYPE);
63	}
64	
65	function spawnServer({ env = {}, cwd, serverPath = SERVER_PATH }) {
66	  const child = spawn(process.execPath, [serverPath], {
67	    cwd, env: baseEnv(env), stdio: ['ignore', 'pipe', 'pipe'],
68	  });
69	  const output = { stdout: '', stderr: '' };
70	  child.stdout.setEncoding('utf8').on('data', (s) => { output.stdout += s; });
71	  child.stderr.setEncoding('utf8').on('data', (s) => { output.stderr += s; });
72	  const exited = new Promise((resolve) => {
73	    child.on('close', (code, signal) => resolve({ code, signal }));
74	  });
75	  return { child, output, exited };
76	}
77	
78	/** Runs the server expecting it to exit by itself; resolves { code, stdout, stderr }. */
79	export async function runToExit({ env = {}, cwd, serverPath, timeoutMs = START_TIMEOUT_MS }) {
80	  const { child, output, exited } = spawnServer({ env, cwd, serverPath });
81	  const timer = setTimeout(() => child.kill('SIGKILL'), timeoutMs);
82	  const { code, signal } = await exited;
83	  clearTimeout(timer);
84	  return { code, signal, stdout: output.stdout, stderr: output.stderr };
85	}
86	
87	/**
88	 * Starts the server and waits for its "listening" line.
89	 * Resolves { port, output, stop() }; stop() kills it and resolves { code, signal }.
90	 * Rejects (after killing the child) when the server exits or stays silent.
91	 */
92	export async function startServer({ env = {}, cwd, serverPath } = {}) {
93	  const proc = spawnServer({ env: { PORT: '0', ...env }, cwd, serverPath });
94	  const stop = async () => {
95	    if (proc.child.exitCode === null && proc.child.signalCode === null) proc.child.kill('SIGKILL');
96	    return proc.exited;
97	  };
98	  try {
99	    const port = await waitForListening(proc);
100	    return { port, output: proc.output, stop, exited: proc.exited };
101	  } catch (err) {
102	    await stop();
103	    throw err;
104	  }
105	}
106	
107	function waitForListening({ child, output, exited }) {
108	  return new Promise((resolve, reject) => {
109	    const timer = setTimeout(() => reject(new Error(`server did not start: ${output.stderr}`)), START_TIMEOUT_MS);
110	    const onData = () => {
111	      const match = /^listening on http:\/\/127\.0\.0\.1:(\d+)\n/.exec(output.stdout);
112	      if (!match) return;
113	      clearTimeout(timer);
114	      child.stdout.off('data', onData);
115	      resolve(Number(match[1]));
116	    };
117	    child.stdout.on('data', onData);
118	    exited.then(({ code }) => {
119	      clearTimeout(timer);
120	      reject(new Error(`server exited with ${code}: ${output.stderr}`));
121	    });
122	  });
123	}
124	
125	/**
126	 * Sends one HTTP request with the path exactly as given (no normalisation).
127	 * Resolves { status, headers, body: Buffer, text, json() }.
128	 */
129	export function request(port, { method = 'GET', path: target = '/', headers = {}, body } = {}) {
130	  return new Promise((resolve, reject) => {
131	    const req = http.request({ host: '127.0.0.1', port, method, path: target, headers, agent: false }, (res) => {
132	      const chunks = [];
133	      res.on('data', (c) => chunks.push(c));
134	      res.on('error', reject);
135	      res.on('end', () => {
136	        const buffer = Buffer.concat(chunks);
137	        const text = buffer.toString('utf8');
138	        resolve({ status: res.statusCode, headers: res.headers, body: buffer, text, json: () => JSON.parse(text) });
139	      });
140	    });
141	    req.on('error', reject);
142	    req.end(body);
143	  });
144	}
145	
146	/** Sends a POST /api/bookings with a JSON content type; `body` may be an object, string or Buffer. */
147	export function postBooking(port, body, headers = { 'Content-Type': 'application/json' }) {
148	  const payload = typeof body === 'string' || Buffer.isBuffer(body) ? body : JSON.stringify(body);
149	  return request(port, { method: 'POST', path: '/api/bookings', headers, body: payload });
150	}
151	
152	/**
153	 * Writes raw bytes to the server and resolves with everything it sends until it closes.
154	 * The socket is not half-closed (Node drops replies to half-closed requests that answer
155	 * asynchronously), so the data must end with a request carrying `Connection: close`.
156	 */
157	export function rawRequest(port, data, timeoutMs = START_TIMEOUT_MS) {
158	  return new Promise((resolve, reject) => {
159	    const socket = net.connect(port, '127.0.0.1');
160	    const chunks = [];
161	    const timer = setTimeout(() => {
162	      socket.destroy();
163	      resolve(Buffer.concat(chunks).toString('latin1'));
164	    }, timeoutMs);
165	    socket.on('data', (c) => chunks.push(c));
166	    socket.on('error', (err) => { clearTimeout(timer); reject(err); });
167	    socket.on('close', () => { clearTimeout(timer); resolve(Buffer.concat(chunks).toString('latin1')); });
168	    socket.write(data);
169	  });
170	}
