172	/**
173	 * Starts one server in a fresh temp folder for a suite.
174	 * Returns an object whose fields (`port`, `dir`, `dataFile`, `server`) are filled by `before`.
175	 * Usage: const ctx = useServer({ before, after });
176	 */
177	export function useServer({ before, after }, { dataFileName = 'data.json', env = {} } = {}) {
178	  const ctx = { port: 0, dir: '', dataFile: '', server: null };
179	  before(async () => {
180	    ctx.dir = await makeTempDir();
181	    ctx.dataFile = path.join(ctx.dir, dataFileName);
182	    ctx.server = await startServer({ env: { DATA_FILE: ctx.dataFile, ...env }, cwd: ctx.dir });
183	    ctx.port = ctx.server.port;
184	  });
185	  after(async () => {
186	    if (ctx.server) await ctx.server.stop();
187	    if (ctx.dir) await removeDir(ctx.dir);
188	  });
189	  return ctx;
190	}
