11	// Replaces textContent on this one element with a getter/setter that keeps the
12	// value and calls onSet(newValue) before storing it. Returns the element.
13	export function spyOnText(element, onSet) {
14	  let stored = element.textContent;
15	  Object.defineProperty(element, 'textContent', {
16	    configurable: true,
17	    get() { return stored; },
18	    set(value) { onSet(value); stored = value; },
19	  });
20	  return element;
21	}
