44	function assertOneLineError(result) {
45	  assert.equal(result.code, 1);
46	  assert.equal(result.stdout, '');
47	  assert.match(result.stderr, /^[^\n]+\n$/);
48	  assert.equal(result.stderr.includes('\n    at '), false);
49	  assert.equal(result.stderr.includes('Error:'), false);
