1	// Booking rules 1-3, body sizes, encodings and full reading of request bodies.
2	import { test, describe, before, after } from 'node:test';
3	import assert from 'node:assert/strict';
4	import {
5	  useServer, request, postBooking, rawRequest, uniqueDate, expectError, JSON_TYPE,
6	} from './helpers/server.mjs';
7	
8	const CT_MSG = 'content type must be application/json';
9	const JSON_CT = { 'Content-Type': 'application/json' };
10	
11	function fields(extra = {}) {
12	  return { room: 'Aurora', title: 'Standup', date: uniqueDate(), start: '09:00', end: '10:00', ...extra };
13	}
14	
15	/** JSON text of a booking padded with trailing spaces to exactly `size` bytes. */
16	function paddedBody(size, extra = {}) {
17	  const text = JSON.stringify(fields(extra));
18	  const padding = size - Buffer.byteLength(text);
19	  assert.ok(padding >= 0, 'fixture larger than requested size');
20	  return text + ' '.repeat(padding);
21	}
22	
23	/** Raw POST /api/bookings bytes with an explicit Content-Type header line (string or Buffer). */
24	function rawPost(contentTypeLine, body, extraHeaders = '') {
25	  const payload = Buffer.isBuffer(body) ? body : Buffer.from(body, 'utf8');
26	  const head = Buffer.concat([
27	    Buffer.from('POST /api/bookings HTTP/1.1\r\nHost: x\r\nContent-Type: ', 'latin1'),
28	    Buffer.isBuffer(contentTypeLine) ? contentTypeLine : Buffer.from(contentTypeLine, 'latin1'),
29	    Buffer.from(`\r\nContent-Length: ${payload.length}\r\n${extraHeaders}Connection: close\r\n\r\n`, 'latin1'),
30	  ]);
31	  return Buffer.concat([head, payload]);
32	}
33	
34	function chunkedPost(body, pieces) {
35	  const buf = Buffer.from(body, 'utf8');
36	  const size = Math.ceil(buf.length / pieces);
37	  const parts = [Buffer.from(
38	    'POST /api/bookings HTTP/1.1\r\nHost: x\r\nContent-Type: application/json\r\n'
39	    + 'Transfer-Encoding: chunked\r\nConnection: close\r\n\r\n', 'latin1')];
40	  for (let i = 0; i < buf.length; i += size) {
41	    const piece = buf.subarray(i, i + size);
42	    parts.push(Buffer.from(`${piece.length.toString(16)}\r\n`), piece, Buffer.from('\r\n'));
43	  }
44	  parts.push(Buffer.from('0\r\n\r\n'));
45	  return Buffer.concat(parts);
46	}
47	
48	function statusOf(raw) {
49	  return Number(/^HTTP\/1\.1 (\d{3})/.exec(raw)?.[1]);
50	}
51	
52	function bodyOf(raw) {
53	  const text = raw.slice(raw.indexOf('\r\n\r\n') + 4);
54	  return JSON.parse(text.slice(text.indexOf('{')));
55	}
56	
57	/**
58	 * Splits raw text holding back-to-back HTTP/1.1 responses (all with Content-Length)
59	 * into { statusLine, headers, body } objects. The text is latin1, so one char is one byte.
60	 */
61	function splitResponses(raw) {
62	  const responses = [];
63	  let rest = raw;
64	  while (rest.length > 0) {
65	    const headEnd = rest.indexOf('\r\n\r\n');
66	    assert.notEqual(headEnd, -1, 'incomplete response head');
67	    const [statusLine, ...headerLines] = rest.slice(0, headEnd).split('\r\n');
68	    const headers = Object.fromEntries(headerLines.map((line) => {
69	      const colon = line.indexOf(':');
70	      return [line.slice(0, colon).toLowerCase(), line.slice(colon + 1).trim()];
71	    }));
72	    assert.match(headers['content-length'] ?? '', /^\d+$/, 'missing Content-Length');
73	    const length = Number(headers['content-length']);
74	    const body = rest.slice(headEnd + 4, headEnd + 4 + length);
75	    assert.equal(body.length, length, 'truncated response body');
76	    responses.push({ statusLine, headers, body });
77	    rest = rest.slice(headEnd + 4 + length);
78	  }
79	  return responses;
80	}
