26	// Removes // and /* */ comments, keeping string and template contents.
27	function stripComments(src) {
28	  let out = '';
29	  for (let i = 0; i < src.length; i += 1) {
30	    const c = src[i];
31	    if (c === '"' || c === "'" || c === '`') {
32	      let j = i + 1;
33	      while (j < src.length && src[j] !== c) j += src[j] === '\\' ? 2 : 1;
34	      out += src.slice(i, j + 1);
35	      i = j;
36	    } else if (c === '/' && src[i + 1] === '/') {
37	      while (i < src.length && src[i] !== '\n') i += 1;
38	      out += '\n';
39	    } else if (c === '/' && src[i + 1] === '*') {
40	      i = src.indexOf('*/', i + 2) + 1;
41	    } else out += c;
42	  }
43	  return out;
44	}
