48	function makeRecorder() {
49	  const accesses = [];
50	  const targets = new WeakMap();
51	  const unwrap = (v) => (v !== null && typeof v === 'object' && targets.has(v) ? targets.get(v) : v);
52	  function wrap(kind, target, ignore = []) {
53	    const proxy = new Proxy(target, {
54	      get(t, prop) {
55	        if (typeof prop === 'symbol' || ignore.includes(prop)) return Reflect.get(t, prop, t);
56	        accesses.push(`${kind}.${prop}`);
57	        const v = Reflect.get(t, prop, t);
58	        if (typeof v !== 'function') return v;
59	        if (prop === 'append' || prop === 'replaceChildren') {
60	          return (...args) => v.apply(t, args.map(unwrap));
61	        }
62	        return v.bind(t);
63	      },
64	      set(t, prop, value) {
65	        accesses.push(`${kind}.${String(prop)}`);
66	        return Reflect.set(t, prop, value, t);
67	      },
68	    });
69	    targets.set(proxy, target);
70	    return proxy;
71	  }
72	  return { accesses, wrap, unwrap };
73	}
