75	// Fake elements built from the real page: one per element that has an id.
76	function buildElementsFromHtml() {
77	  const html = readFileSync(new URL('../public/index.html', import.meta.url), 'utf8');
78	  const elements = new Map();
79	  for (const node of parseHtml(html)) {
80	    const id = node.attrs.get('id');
81	    if (!id) continue;
82	    const element = new FakeElement(node.tag, id);
83	    if (node.attrs.has('type')) element.type = node.attrs.get('type');
84	    if (node.tag === 'button') element.textContent = node.innerText;
85	    elements.set(id, element);
86	  }
87	  return elements;
88	}
