90	function makeFetch(rec, calls) {
91	  return (url, options) => new Promise((resolve, reject) => {
92	    for (const key of Object.keys(options ?? {})) rec.accesses.push(`fetchOption.${key}`);
93	    const reply = (status, body) => resolve(rec.wrap('response', {
94	      status, json: () => Promise.resolve(body),
95	    }, ['then']));
96	    calls.push({ url, options, reply, reject: () => reject(new TypeError('fetch failed')) });
97	  });
98	}
