100	function loadRecorded(source) {
101	  const rec = makeRecorder();
102	  const calls = [];
103	  const els = buildElementsFromHtml();
104	  const proxies = new Map();
105	  const doc = {
106	    getElementById: (id) => {
107	      if (!proxies.has(id)) proxies.set(id, rec.wrap('element', els.get(id)));
108	      return proxies.get(id);
109	    },
110	    createElement: (tag) => rec.wrap('element', new FakeElement(tag)),
111	  };
112	  const document = rec.wrap('document', doc);
113	  const context = vm.createContext({ document, fetch: makeFetch(rec, calls) });
114	  vm.runInContext(source, context, { filename: 'app.js' });
115	  const fire = (target, type) => {
116	    const event = { type, defaultPrevented: false, preventDefault() { this.defaultPrevented = true; } };
117	    const proxy = rec.wrap('event', event);
118	    for (const fn of target.listeners[type] || []) fn(proxy);
119	    return event;
120	  };
121	  return { rec, calls, els, context, fire, syncCalls: calls.length };
122	}
