145	    await answer(200, { bookings: [AURORA_BOOKING, COSMOS_BOOKING] });
146	    for (const [id, v] of [['room', 'Aurora'], ['title', 'T'], ['date', '2026-11-03'],
147	      ['start', '09:00'], ['end', '10:00']]) els.get(id).value = v;
148	    fire(els.get('booking-form'), 'submit');
149	    await answer(201, AURORA_BOOKING);
150	    await answer(200, { bookings: [AURORA_BOOKING] });
151	    fire(els.get('booking-form'), 'submit');
152	    await answer(409, { error: 'room is already booked from 09:00 to 10:00' });
153	    fire(els.get('booking-list').childNodes[0]?.childNodes[1] ?? els.get('book'), 'click');
154	    await answer(204);
155	    await answer(200, { bookings: [AURORA_BOOKING] });
156	    fire(els.get('booking-list').childNodes[0]?.childNodes[1] ?? els.get('book'), 'click');
157	    calls[idx]?.reject();
158	    idx += 1;
159	    await flush();
