164	    fire(els.get('show-all'), 'click');
165	    await answer(200, { bookings: [] });
166	    await flush();
167	    return { page, rejections, urls: calls.map((c) => c.url) };
168	  } finally {
169	    process.removeListener('unhandledRejection', onRejection);
170	  }
