1	import { readFileSync } from 'node:fs';
2	import vm from 'node:vm';
3	
4	const APP_URL = new URL('../../public/app.js', import.meta.url);
5	
6	function textNode(data) {
7	  return { nodeType: 3, data: String(data) };
8	}
9	
10	function toNodes(items) {
11	  return items.map((item) => (typeof item === 'string' ? textNode(item) : item));
12	}
13	
14	function nodeText(node) {
15	  return node.nodeType === 3 ? node.data : node.textContent;
16	}
17	
18	export class FakeElement {
19	  constructor(tagName, id = '') {
20	    this.nodeType = 1;
21	    this.tagName = tagName.toUpperCase();
22	    this.id = id;
23	    this.type = '';
24	    this.disabled = false;
25	    this.childNodes = [];
26	    this.listeners = {};
27	    this.rawValue = undefined;
28	  }
29	
30	  get value() {
31	    if (this.rawValue !== undefined) return this.rawValue;
32	    if (this.tagName === 'SELECT') {
33	      const first = this.childNodes.find((n) => n.tagName === 'OPTION');
34	      return first ? first.value : '';
35	    }
36	    return '';
37	  }
38	
39	  set value(v) {
40	    this.rawValue = String(v);
41	  }
42	
43	  get textContent() {
44	    return this.childNodes.map(nodeText).join('');
45	  }
46	
47	  set textContent(text) {
48	    const s = String(text);
49	    this.childNodes = s === '' ? [] : [textNode(s)];
50	  }
51	
52	  append(...nodes) {
53	    this.childNodes = this.childNodes.concat(toNodes(nodes));
54	  }
55	
56	  replaceChildren(...nodes) {
57	    this.childNodes = toNodes(nodes);
58	  }
59	
60	  addEventListener(type, fn) {
61	    (this.listeners[type] ||= []).push(fn);
62	  }
63	
64	  dispatch(type) {
65	    const event = {
66	      type,
67	      defaultPrevented: false,
68	      preventDefault() { this.defaultPrevented = true; },
69	    };
70	    for (const fn of this.listeners[type] || []) fn(event);
71	    return event;
72	  }
73	}
74	
75	const SPECS = [
76	  ['booking-form', 'form'], ['room', 'select'], ['title', 'input', 'text'],
77	  ['date', 'input', 'date'], ['start', 'input', 'time'], ['end', 'input', 'time'],
78	  ['book', 'button', 'submit', 'Book'], ['filter-date', 'input', 'date'],
79	  ['show-all', 'button', 'button'], ['booking-list', 'ul'], ['error', 'p'],
80	];
81	
82	function buildElements() {
83	  const byId = new Map();
84	  for (const [id, tag, type, text] of SPECS) {
85	    const e = new FakeElement(tag, id);
86	    if (type) e.type = type;
87	    if (text) e.textContent = text;
88	    byId.set(id, e);
89	  }
90	  return byId;
91	}
92	
93	function buildDocument(byId) {
94	  const document = Object.create(null);
95	  document.getElementById = (id) => byId.get(id) ?? null;
96	  document.createElement = (tag) => new FakeElement(tag);
97	  return document;
98	}
99	
100	function makeControlledFetch(calls) {
101	  return (url, options) => new Promise((resolve, reject) => {
102	    const call = {
103	      url, options, jsonCalls: 0,
104	      resolveWith: (response) => resolve(response),
105	      resolve(status, body) {
106	        resolve({ status, json: () => { call.jsonCalls += 1; return Promise.resolve(body); } });
107	      },
108	      resolveBadJson(status) {
109	        resolve({
110	          status,
111	          json: () => { call.jsonCalls += 1; return Promise.reject(new SyntaxError('bad json')); },
112	        });
113	      },
114	      reject() { reject(new TypeError('fetch failed')); },
115	    };
116	    calls.push(call);
117	  });
118	}
119	
120	async function flush(turns = 5) {
121	  for (let i = 0; i < turns; i += 1) await new Promise((r) => setImmediate(r));
122	}
123	
124	export function loadPage({ fetchImpl } = {}) {
125	  const calls = [];
126	  const byId = buildElements();
127	  const document = buildDocument(byId);
128	  const fetch = fetchImpl ?? makeControlledFetch(calls);
129	  const source = readFileSync(APP_URL, 'utf8');
130	  const context = vm.createContext({ document, fetch });
131	  vm.runInContext(source, context, { filename: 'app.js' });
132	  return { document, el: (id) => byId.get(id), calls, flush };
133	}
134	
135	function summarizeNode(node) {
136	  if (node.nodeType === 3) return { text: node.data };
137	  return { tag: node.tagName, type: node.type, text: node.textContent, disabled: node.disabled };
138	}
139	
140	export function listTexts(ul) {
141	  return ul.childNodes.map((li) => {
142	    const [first, second] = li.childNodes;
143	    return {
144	      text: first && first.nodeType === 3 ? first.data : undefined,
145	      button: second && second.tagName === 'BUTTON'
146	        ? { type: second.type, text: second.textContent, disabled: second.disabled }
147	        : undefined,
148	      childCount: li.childNodes.length,
149	      nodes: li.childNodes.map(summarizeNode),
150	    };
151	  });
152	}
