1	// Runs the test suite once per near-miss copy (testing section tool).
2	// Works on a scratch copy of the project in the OS temp folder, so the real originals are never
3	// touched (another section may edit them meanwhile). Inside the scratch copy each near-miss is
4	// swapped into place, the suite runs, and the original is restored, also when the run fails.
5	// Usage: node .team/tools/near-miss-run.mjs [<n> ...]   -> prints one line per near-miss.
6	import { spawnSync } from 'node:child_process';
7	import { cpSync, mkdtempSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
8	import os from 'node:os';
9	import path from 'node:path';
10	
11	const ROOT = path.resolve(new URL('../..', import.meta.url).pathname);
12	const NEAR = path.join(ROOT, '.team/near-miss');
13	const TARGETS = { 'server.mjs': 'server.mjs', 'app.js': 'public/app.js', 'index.html': 'public/index.html' };
14	
15	function targetOf(file) {
16	  const base = file.replace(/^\d+-/, '');
17	  if (!Object.hasOwn(TARGETS, base)) throw new Error(`unknown near-miss target: ${file}`);
18	  return TARGETS[base];
19	}
20	
21	function runSuite(dir) {
22	  const env = { ...process.env };
23	  delete env.NODE_TEST_CONTEXT;
24	  const r = spawnSync(process.execPath, ['--test', 'test/**/*.test.mjs'], {
25	    cwd: dir, env, encoding: 'utf8', timeout: 240000, maxBuffer: 64 * 1024 * 1024,
26	  });
27	  const failed = [...r.stdout.matchAll(/^\s*not ok \d+ - (.*)$/gm)].map((m) => m[1]);
28	  return { code: r.status, failed };
29	}
30	
31	const scratch = mkdtempSync(path.join(os.tmpdir(), 'near-miss-'));
32	try {
33	  for (const part of ['server.mjs', 'package.json', 'public', 'test']) {
34	    cpSync(path.join(ROOT, part), path.join(scratch, part), { recursive: true });
35	  }
36	  const only = new Set(process.argv.slice(2));
37	  const files = readdirSync(NEAR)
38	    .filter((f) => only.size === 0 || only.has(f.split('-')[0]))
39	    .sort((a, b) => parseInt(a, 10) - parseInt(b, 10));
40	  for (const file of files) {
41	    const target = path.join(scratch, targetOf(file));
42	    const original = readFileSync(target);
43	    const bug = readFileSync(path.join(NEAR, file), 'utf8').split('\n', 1)[0];
44	    writeFileSync(target, readFileSync(path.join(NEAR, file)));
45	    let result;
46	    try {
47	      result = runSuite(scratch);
48	    } finally {
49	      writeFileSync(target, original);
50	    }
51	    const verdict = result.code === 0 ? 'SURVIVED' : 'killed';
52	    process.stdout.write(`${verdict} ${file} ${bug} | ${result.failed.slice(0, 4).join(' ; ')}\n`);
53	  }
54	  const clean = runSuite(scratch);
55	  process.stdout.write(`originals in scratch: exit ${clean.code}\n`);
56	} finally {
57	  rmSync(scratch, { recursive: true, force: true });
58	}
